import React from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

const CrimeStats = ({ crimes }) => {
  if (!crimes || crimes.length === 0) return <div>No data available.</div>;

  // Count occurrences per CrimeCode
  const crimeCounts = crimes.reduce((acc, c) => {
    acc[c.CrimeCode] = (acc[c.CrimeCode] || 0) + 1;
    return acc;
  }, {});

  const chartData = Object.keys(crimeCounts).map((key) => ({
    CrimeCode: key,
    Count: crimeCounts[key],
  }));

  return (
    <div>
      <h2>Crime Statistics</h2>
      <p>Total Crimes: {crimes.length}</p>

      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={chartData}>
          <XAxis dataKey="CrimeCode" />
          <YAxis />
          <Tooltip />
          <Bar dataKey="Count" fill="#8884d8" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default CrimeStats;
